package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.util.concurrent.*;
final class DashboardsAcceptance {
 static final String API="/api/openservice/dashboards";
 static Map<String,Object> body(String report,int revision,String visibility,List<?> groups){return map("revision",revision,"name","Service operations <script>","visibility",visibility,"groups",groups,"widgets",List.of(map("report_id",report,"metric","average"),map("report_id",report,"metric","count")));}
 static Map<String,Object> save(WorkflowSupport h,String id,Map<String,Object> body,String actor)throws Exception {var response=h.json("POST",API+(id.isEmpty()?"":"/"+id),body,auth(actor));assertEquals(id.isEmpty()?201:200,response.statusCode(),html(response));return result(response);}
 static Map<String,Object> show(WorkflowSupport h,String id,String actor)throws Exception {var response=h.get(API+"/"+id,auth(actor));assertEquals(200,response.statusCode(),html(response));return result(response);}
 static String group(Store store,String name,String member)throws Exception {try(var db=store.open()){PlatformFoundationTest.bind(db);String group=Service.create(db,"sys_user_group",map("short_description",name),"admin").get("sys_id").toString();GroupMembers.change(db,group,db.viewerId,map("user_id",RecordAccess.owner(db,member)),true);db.connection.commit();return group;}}
 static void run(WorkflowSupport h)throws Exception {
  var f=ReportSchedulesAcceptance.seed(h.store);String report=f.get("report").toString();assertEquals(200,h.get(API,auth("admin")).statusCode());var board=save(h,"",body(report,0,"workspace",List.of()),"admin");String id=board.get("dashboard_id").toString();assertEquals(true,board.get("can_manage"));assertEquals("50",objects(board.get("widgets")).getFirst().get("value"));h.account("DashboardReader","reader");var view=show(h,id,"DashboardReader");assertEquals(false,view.get("can_manage"));assertEquals("10",objects(view.get("widgets")).getFirst().get("value"));assertEquals("1",objects(view.get("widgets")).getLast().get("value"));assertFalse(view.containsKey("definition"));assertEquals(1,objects(parsed(h.get(API,auth("DashboardReader"))).get("result")).size());new Store(h.environment);assertEquals("10",objects(show(h,id,"DashboardReader").get("widgets")).getFirst().get("value"));
  var changed=body(report,1,"workspace",List.of());changed.put("widgets",List.of(map("report_id",report,"metric","count"),map("report_id",report,"metric","sum")));assertEquals("count",objects(save(h,id,changed,"admin").get("widgets")).getFirst().get("metric"));save(h,id,body(report,2,"private",List.of()),"admin");assertEquals(404,h.get(API+"/"+id,auth("DashboardReader")).statusCode());assertEquals(0,objects(parsed(h.get(API,auth("DashboardReader"))).get("result")).size());assertEquals(200,h.json("POST",API+"/"+id+"/delete",map("revision",3),auth("admin")).statusCode());assertEquals(404,h.get(API+"/"+id,auth("admin")).statusCode());assertEquals(200,h.get("/reports/"+report,auth("admin")).statusCode());
 }
 static void groups(WorkflowSupport h)throws Exception {
  var f=ReportSchedulesAcceptance.seed(h.store);String report=f.get("report").toString();h.account("DashboardTeam","reader");h.account("DashboardOutside","reader");String team=group(h.store,"Operations review team","DashboardTeam");var board=save(h,"",body(report,0,"groups",List.of(team)),"admin");String id=board.get("dashboard_id").toString();assertEquals("10",objects(show(h,id,"DashboardTeam").get("widgets")).getFirst().get("value"));assertEquals(404,h.get(API+"/"+id,auth("DashboardOutside")).statusCode());try(var db=h.store.open()){PlatformFoundationTest.bind(db);GroupMembers.change(db,team,db.viewerId,map("user_id",RecordAccess.owner(db,"DashboardTeam")),false);db.connection.commit();}assertEquals(404,h.get(API+"/"+id,auth("DashboardTeam")).statusCode());try(var db=h.store.open()){PlatformFoundationTest.bind(db);GroupMembers.change(db,team,db.viewerId,map("user_id",RecordAccess.owner(db,"DashboardTeam")),true);db.connection.commit();}assertEquals(200,h.get(API+"/"+id,auth("DashboardTeam")).statusCode());try(var db=h.store.open()){db.update("DELETE FROM os_record WHERE sys_id=?",team);db.connection.commit();}assertEquals(404,h.get(API+"/"+id,auth("DashboardTeam")).statusCode());assertEquals(200,h.get(API+"/"+id,auth("admin")).statusCode());
 }
 static void permissions(WorkflowSupport h)throws Exception {
  var f=ReportSchedulesAcceptance.seed(h.store);String report=f.get("report").toString();h.account("DashboardOther","admin");h.account("DashboardAgent","agent");h.account("DashboardRead","reader");h.account("DashboardRequester","requester");var board=save(h,"",body(report,0,"private",List.of()),"admin");String id=board.get("dashboard_id").toString();assertEquals(401,h.get(API,null).statusCode());assertEquals(403,h.get(API,auth("DashboardRequester")).statusCode());assertEquals(403,h.get(API+"/"+id,auth("DashboardRequester")).statusCode());assertEquals(403,h.json("POST",API,body(report,0,"workspace",List.of()),auth("DashboardRead")).statusCode());assertEquals(403,h.get("/dashboards/new",auth("DashboardRead")).statusCode());assertEquals(404,h.get(API+"/"+id,auth("DashboardOther")).statusCode());assertEquals(404,h.get("/dashboards/"+id+"/edit",auth("DashboardOther")).statusCode());save(h,id,body(report,1,"workspace",List.of()),"admin");assertEquals(404,h.json("POST",API+"/"+id,body(report,2,"private",List.of()),auth("DashboardOther")).statusCode());assertEquals(404,h.json("POST",API+"/"+id+"/delete",map("revision",2),auth("DashboardOther")).statusCode());assertEquals(403,h.json("POST",API+"/"+id+"/delete",map("revision",2),auth("DashboardRead")).statusCode());assertEquals(403,h.form("/dashboards",map("name","No CSRF"),auth("admin")).statusCode());assertEquals(403,h.form("/dashboards/"+id+"/delete",map("revision","2"),auth("admin")).statusCode());assertEquals(201,h.json("POST",API,body(report,0,"workspace",List.of()),auth("DashboardAgent")).statusCode());
 }
 static void unavailable(WorkflowSupport h)throws Exception {
  var f=ReportSchedulesAcceptance.seed(h.store);String report=f.get("report").toString();h.account("DashboardViewer","reader");String board=save(h,"",body(report,0,"workspace",List.of()),"admin").get("dashboard_id").toString();try(var db=h.store.open()){db.update("UPDATE os_saved_report SET shared=0 WHERE report_id=?",report);db.connection.commit();}var hidden=objects(show(h,board,"DashboardViewer").get("widgets")).getFirst();assertEquals(map("available",false,"name","Report unavailable"),hidden);assertFalse(JSON.writeValueAsString(show(h,board,"DashboardViewer")).contains(report));assertEquals(true,objects(show(h,board,"admin").get("widgets")).getFirst().get("available"));
  Map<String,Object> definition;try(var db=h.store.open()){db.update("UPDATE os_saved_report SET shared=1 WHERE report_id=?",report);definition=Service.schema(db,f.get("table").toString());var denied=new LinkedHashMap<>(definition);denied.put("record_roles",map("read",List.of("admin")));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name=?",JSON.writeValueAsString(denied),f.get("table"));db.connection.commit();}try{assertEquals(false,objects(show(h,board,"DashboardViewer").get("widgets")).getFirst().get("available"));}finally{try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name=?",JSON.writeValueAsString(definition),f.get("table"));db.connection.commit();}}
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);SavedReports.save(db,db.viewerId,report,map("name","Now grouped","table",f.get("table"),"query",map("field","amount","group_by","short_description"),"shared",true));db.connection.commit();}assertEquals(false,objects(show(h,board,"admin").get("widgets")).getFirst().get("available"));try(var db=h.store.open()){PlatformFoundationTest.bind(db);SavedReports.remove(db,db.viewerId,report);db.connection.commit();}assertEquals(false,objects(show(h,board,"DashboardViewer").get("widgets")).getFirst().get("available"));assertEquals(200,h.json("POST",API+"/"+board+"/delete",map("revision",1),auth("admin")).statusCode());
 }
 static void validation(WorkflowSupport h)throws Exception {
  var f=ReportSchedulesAcceptance.seed(h.store);String report=f.get("report").toString(),team=group(h.store,"Validation team","admin");for(var change:List.of(map("revision","0"),map("revision",-1),map("name"," "),map("name","a".repeat(161)),map("visibility","unknown"),map("groups","bad"),map("groups",List.of(team)),map("widgets","bad"),map("widgets",List.of()),map("widgets",Collections.nCopies(9,map("report_id",report,"metric","count"))),map("widgets",List.of(map())),map("widgets",List.of(map("report_id","bad","metric","count"))),map("widgets",List.of(map("report_id",report,"metric","median"))),map("widgets",Collections.nCopies(2,map("report_id",report,"metric","count"))))){var b=body(report,0,"workspace",List.of());b.putAll(change);assertEquals(400,h.json("POST",API,b,auth("admin")).statusCode(),b.toString());}
  for(Object groups:List.of(List.of(),Collections.nCopies(6,team),List.of(team,team),List.of(1),List.of("bad"))){var b=body(report,0,"groups",List.of());b.put("groups",groups);assertEquals(400,h.json("POST",API,b,auth("admin")).statusCode());}assertEquals(404,h.json("POST",API,body(report,0,"groups",List.of(id())),auth("admin")).statusCode());assertEquals(400,h.json("POST",API,map(),auth("admin")).statusCode());assertEquals(409,h.json("POST",API,body(report,1,"workspace",List.of()),auth("admin")).statusCode());assertEquals(405,h.json("DELETE",API,map(),auth("admin")).statusCode());assertEquals(400,h.get(API+"?q=bad",auth("admin")).statusCode());assertEquals(400,h.get(API+"?q=1&q=2",auth("admin")).statusCode());
  var board=save(h,"",body(report,0,"workspace",List.of()),"admin");String id=board.get("dashboard_id").toString();var bad=body(report,1,"private",List.of());bad.put("widgets",List.of(map("report_id",report,"metric","sum"),map("report_id",id(),"metric","sum")));assertEquals(404,h.json("POST",API+"/"+id,bad,auth("admin")).statusCode());assertEquals(1,show(h,id,"admin").get("revision"));assertEquals("workspace",show(h,id,"admin").get("visibility"));assertEquals(409,h.json("POST",API+"/"+id,body(report,0,"private",List.of()),auth("admin")).statusCode());assertEquals(405,h.get(API+"/"+id+"/delete",auth("admin")).statusCode());for(var b:List.of(map(),map("revision","1")))assertEquals(400,h.json("POST",API+"/"+id+"/delete",b,auth("admin")).statusCode());assertEquals(409,h.json("POST",API+"/"+id+"/delete",map("revision",0),auth("admin")).statusCode());
 }
 static void concurrency(WorkflowSupport h)throws Exception {var f=ReportSchedulesAcceptance.seed(h.store);String report=f.get("report").toString(),id=save(h,"",body(report,0,"workspace",List.of()),"admin").get("dashboard_id").toString();try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->h.json("POST",API+"/"+id,body(report,1,"private",List.of()),auth("admin")).statusCode());var b=pool.submit(()->h.json("POST",API+"/"+id,body(report,1,"workspace",List.of()),auth("admin")).statusCode());assertEquals(Set.of(200,409),Set.of(a.get(),b.get()));}assertEquals(2,show(h,id,"admin").get("revision"));} static void limitsAndMetrics(WorkflowSupport h)throws Exception {
  var f=ReportSchedulesAcceptance.seed(h.store);String report=f.get("report").toString(),second=ReportMeasurementsAcceptance.save(h.store,f.get("table").toString(),map("field","amount","q","short_description=Absent"),true);var widgets=new ArrayList<Map<String,Object>>();for(String metric:List.of("count","value_count","sum","min","max","average"))widgets.add(map("report_id",report,"metric",metric));widgets.add(map("report_id",second,"metric","count"));widgets.add(map("report_id",second,"metric","average"));var body=body(report,0,"workspace",List.of());body.put("widgets",widgets);var board=save(h,"",body,"admin");var values=objects(board.get("widgets"));assertEquals(List.of("2","2","100","10","90","50","0"),values.subList(0,7).stream().map(row->row.get("value")).toList());assertNull(values.getLast().get("value"));String id=board.get("dashboard_id").toString();try(var db=h.store.open()){PlatformFoundationTest.bind(db);assertEquals(8,objects(Dashboards.editor(db,id).get("slots")).size());String definition=JSON.writeValueAsString(map("widgets",widgets));for(int n=0;n<49;n++)db.update("INSERT INTO os_dashboard(dashboard_id,owner_id,name,visibility,revision,definition) VALUES(?,?,'Capacity','private',1,?)",id(),db.viewerId,definition);db.connection.commit();}assertEquals(400,h.json("POST",API,body(report,0,"workspace",List.of()),auth("admin")).statusCode());try(var db=h.store.open()){for(int n=0;n<205;n++)db.update("INSERT INTO os_dashboard(dashboard_id,owner_id,name,visibility,revision,definition) VALUES(?,?,'Shared capacity','workspace',1,?)",id(),id(),JSON.writeValueAsString(map("widgets",widgets)));db.connection.commit();}assertEquals(200,objects(parsed(h.get(API,auth("admin"))).get("result")).size());
 }
 static void roleAndFields(WorkflowSupport h)throws Exception {
  var f=ReportSchedulesAcceptance.seed(h.store);String report=f.get("report").toString();h.account("DashboardAuthor","agent");String board=save(h,"",body(report,0,"private",List.of()),"DashboardAuthor").get("dashboard_id").toString();try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.changeRole(db,db.viewerId,RecordAccess.owner(db,"DashboardAuthor"),map("role","reader"));db.connection.commit();}assertEquals(false,show(h,board,"DashboardAuthor").get("can_manage"));assertEquals(403,h.json("POST",API+"/"+board,body(report,1,"workspace",List.of()),auth("DashboardAuthor")).statusCode());Map<String,Object> definition;try(var db=h.store.open()){definition=Service.schema(db,f.get("table").toString());var denied=Service.schema(db,f.get("table").toString());object(denied.get("fields")).remove("amount");object(denied.get("field_rules")).remove("amount");db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name=?",JSON.writeValueAsString(denied),f.get("table"));db.connection.commit();}try{assertEquals(false,objects(show(h,board,"DashboardAuthor").get("widgets")).getFirst().get("available"));}finally{try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name=?",JSON.writeValueAsString(definition),f.get("table"));db.connection.commit();}}
 }

}
